+	"runtime"
+	"sync"
+	"sync/atomic"
+)
+
+// runParallel runs every task on a bounded set of worker goroutines so that a
+// worker reuses its already grown stack across tasks instead of each task
+// starting on a fresh goroutine.
+func runParallel(tasks []func()) {
+	workers := min(runtime.GOMAXPROCS(0), len(tasks))
+	var next atomic.Int64
+	var wg sync.WaitGroup
+	for range workers {
+		wg.Go(func() {
+			for {
+				i := int(next.Add(1)) - 1
+				if i >= len(tasks) {
+					return
+				}
+				tasks[i]()
+			}
+		})
+	}
+	wg.Wait()
+}
